    // Penalize creating bins that are likely to be underutilized
    if bin_capacity - post_residual > 50 {
        score += (bin_capacity - post_residual - 50) as f64 * 0.1;
    }

    // Reward using bins with higher residual space
    if mean_residual < post_residual {
        score -= (post_residual - mean_residual) as f64 * 0.2;
    }

    // Penalize creating new bins if there are fitting open bins available
    if fitting_bins_count > 1 {
        score += 1.0;
    }

    // Reward using bins that have the next item size, reducing waste
    if post_residual >= next_item_size {
        score -= (next_item_size - post_residual) as f64 * 0.3;
    }

